 auto s=original;s.relation_fact_id="family_collateral:1";s.context.role_id.clear();s.context.kind="narrative";s.collateral_dialogue.emplace();auto& p=*s.collateral_dialogue;p.opening_fact_id="known_personal_dialogue_opened:1";p.template_id="template";p.listener_origin={"installed_actor","first",{},{},{}};p.provider_origin={"installed_actor","second",{},{},{}};p.declaration.speaker_actor_id="second";auto& m=p.declaration.meeting;m.source_identity.world_id=s.world_id;m.source_identity.execution_epoch=1;m.source_identity.tick=s.tick;m.source_identity.revision=s.revision;m.actor_id=s.predecessor_actor_id;m.provider_actor_id=s.successor_actor_id;m.session_id=s.session_id;m.dialogue_id=s.dialogue_id;m.node_id=s.node_id;m.node_kind=s.node_kind;m.context=s.context;auto ledger=state(s);auto j3=encode_family_legacy_v3(ledger);check(!decode_family_legacy(j3).ok&&!decode_family_legacy_v2(j3).ok,"Legacy3 cannot be cold read as old format");auto d3=decode_family_legacy_v3(j3);check(d3.ok&&d3.value.consents.find("family_legacy:3")->source.collateral_dialogue&&compare_boundary(j3,encode_family_legacy_v3(d3.value)).exact(),"Legacy3 exact source round trip");check(!decode_family_legacy_v3(j2).ok,"Legacy3 missing explicit new field refused");check(refuses([&]{(void)encode_family_legacy(ledger);})&&refuses([&]{(void)encode_family_legacy_v2(ledger);}),"old writers cannot silently drop new personal declaration");auto empty3=encode_family_legacy_v3(old);check(empty3.find("consents")->find("family_legacy:3")->find("source")->find("collateral_dialogue")->as<std::monostate>(),"new format explicit absence for old relationship kinds");
